{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "high",
      "file": "cloud_pilot/live/engine.py; cloud_pilot/live/stages.py; cloud_pilot/multilingual/delivery.py; cloud_pilot/multilingual/localize.py",
      "detail": "Research and writing artifacts are persisted under cloud_pilot/live_artifacts rather than the permitted daily research, articles, QA or deliveries paths. The writing packet also takes research_baseline_sha from the pre-research plan; it does not record the commit containing the completed research handoff as the writing baseline.",
      "required_fix": "Persist the Fact Sheet, Source Log and handoff within the Research file boundary, push them and bind Writing to the actual research-completion commit. Store writing outputs within the permitted Writing paths and retain immutable versioning."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/engine.py; cloud_pilot/multilingual/__main__.py",
      "detail": "Engine.run retrieves or restores evidence before calling EditorialState.begin. A new evidence epoch can therefore be collected while the previous research head remains writable, contrary to the required lock-before-research and immediate stale-writer invalidation protocol.",
      "required_fix": "Acquire the shared research lock and invalidate the prior head before any evidence refresh or transfer for that article. Keep the lock in force on retrieval failure and test the active Engine path during a concurrent update."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/editorial_state.py; cloud_pilot/live/engine.py; cloud_pilot/multilingual/localize.py",
      "detail": "Research transitions and delivery are not atomic. Multiple pending research starts can select the same next version, and one can mark the head ready while another remains in progress. Separately, a research update can occur after a pre-delivery check but before a draft PR or localized artifact is created; the subsequent check fails only after the stale artifact exists.",
      "required_fix": "Use an atomic, versioned lock/head transition with fencing for writing and delivery. Prevent or invalidate stale draft artifacts and PRs, and add interleaving tests covering concurrent research, writing, localization and delivery."
    },
    {
      "severity": "medium",
      "file": "cloud_pilot/multilingual/editorial_state.py",
      "detail": "If registration writes research-current but stops before writing RESEARCH_READY, a retry sees the matching current row and returns without restoring the ready transition. The subsequent writing-lock check remains blocked by RESEARCH_LOCK, so the documented resume path cannot recover automatically.",
      "required_fix": "Make head registration and readiness atomic or explicitly recover the incomplete transition. Add a crash-and-resume test between those checkpoints without resending a completed model request."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
